insert into public.questions (id, paper_id, topic_id, stem, explanation, position)
values ('dc6b3c1e-e674-5711-baaf-65db00921058', 'bf5dffa9-fe87-5747-9d7e-b6fdfea620f2', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Surds'),
        'Simplify $\sqrt{75} - \sqrt{27} + \sqrt{12}$.',
        '$\sqrt{75} = \sqrt{25 \times 3} = 5\sqrt{3}$

$\sqrt{27} = \sqrt{9 \times 3} = 3\sqrt{3}$

$\sqrt{12} = \sqrt{4 \times 3} = 2\sqrt{3}$

So $5\sqrt{3} - 3\sqrt{3} + 2\sqrt{3} = 4\sqrt{3}$.

**Why the other options are wrong**

- $\sqrt{60}$: Surds do not combine like that: $\sqrt{75} - \sqrt{27} + \sqrt{12}$ is not $\sqrt{75 - 27 + 12}$. Simplify each surd first.
- $6\sqrt{3}$: You took $\sqrt{12}$ as $4\sqrt{3}$. Only the square root of 4 comes out: $\sqrt{12} = \sqrt{4 \times 3} = 2\sqrt{3}$.
- $10\sqrt{3}$: You added all three terms. The middle one is subtracted.',
        1)
