  ('99796f76-ffc1-5824-b321-bd535f4c1b44'::uuid, '58ae25b4-663d-5a75-b8bf-2362aaa42feb'::uuid, 'C', '$x = \dfrac{y + 3}{y - 2}$', true, 2),
